\section{Preliminaries}
\label{sect:Preliminaries}

Throughout the paper, we use the standard graph theoretic notation. For any graph, we use $V(\cdot)$ and $E(\cdot)$ to denote its vertex set and edge set respectively. If there is no other specification, $G$ will denote the graph on which we build the oracle and we set $n=|V(G)|$ and $m=|E(G)|$. Given a graph $G=(V(G),E(G))$, for any $S\subseteq V(G)$, we let $G[S]$ denote the subgraph of $G$ induced by vertices $S$, and let $N_{G}(S)=\{u\mid (u,v)\in E(G),u\notin S,v\in S\}$ denote the set of vertices adjacent to $S$. Also, for any $S\subseteq V(G)$, we use $G\setminus S$ to denote the graph after removing vertices in $S$ and edges incident to them. Similarly, for any $F\subseteq E(G)$, $G\setminus F$ denote the graph after removing edges in $F$.

We also use the notion of \textit{multisets}. A multiset $M$ is a set but allows repeated elements. We let $|M|$ denote its size counting multiplicity, while we let $\Vert M\Vert_{0}$ denote its size without multiplicity. For two multisets $M_{1}$ and $M_{2}$, we call their multiset-union as their \textit{sum}, denoted by $M_{1}+M_{2}$, and we use $\sum_{i=1}^{k}M_{i}$ denote the multiset-union of several multisets $M_{1},...,M_{k}$. The intersection of a multiset $M$ and a set $S$ is still a multiset denoted by $M\cap S$. Concretely, for each element of $M$, it will be kept in $M\cap S$ if it is in $S$, otherwise it will be dropped.

\section{Weighted Vertex Expander Decomposition}
\label{sect:VertexExpander}

For simplicity, we denote the total weight for a set $S\subseteq V(G)$ by $w(S)=\sum_{v\in S}w(v)$, and similarly the total demand for $S$ is $\d(S)=\sum_{v\in S}\d(v)$\footnote{We use such notations for other weight functions throughout the paper.}.

\begin{definition}[Weighted Vertex Expansion]
Let $G=(V(G),E(G),w,\d)$ be a graph with weight $w(v)\geq 0$ and demand $\d(v)\geq 0$ for vertex each $v\in V(G)$. A \textit{vertex cut} of $G$ is a partition $(L,S,R)$ of $V(G)$ such that $(u,v)\notin E(G)$ for all $u\in L,v\in R$. For any vertex cut $(L,S,R)$ of $G$, if $\d(L\cup S)>0$ and $\d(R\cup S)>0$, it has \textit{vertex expansion} 
\[
h_{G}(L,S,R)=\frac{w(S)}{\min\{\d(L\cup S),\d(R\cup S)\}}.
\]
The vertex expansion of $G$, denoted by $h(G)$, is the minimum vertex expansion of any vertex cut $(L,S,R)$ of $G$ with $\d(L\cup S),\d(R\cup S)>0$.
\label{def:VertexExpansion}
\end{definition}

\begin{definition}[Weighted Vertex Expander Decomposition]
Let $G=(V(G),E(G),w,\d)$ be a graph with weight $w(v)\geq 0$ and demand $\d(v)\geq 0$ for each vertex $v\in V(G)$. For parameters $\epsilon>\phi> 0$, an \textit{$(\epsilon,\phi)$-vertex expander decomposition} of $G$ is a collection ${\cal G}=(V_{1},...,V_{k})$ of disjoint subsets of $V(G)$. Let $X=V(G)\setminus (\bigcup_{i} V_{i}$) denote the \textit{separator}. Then ${\cal G}$ further satisfies the following.
\begin{itemize}
    \item     for each pair of distinct $V_{i},V_{i'}\in{\cal G}$, there is no edge connecting $V_{i}$ and $V_{i'}$,
    \item for all $V_{i}\in{\cal G}$, $h(G[V_{i}])\geq\phi$, and
    \item $w(X)\leq \epsilon\cdot\d(V(G))$.
\end{itemize}
\label{def:Decomp}
\end{definition}

\begin{theorem}
Let $G=(V(G),E(G),w,\d)$ be an $n$-vertex $m$-edge graph with for each $v\in V(G)$, integral weight $1\leq w(v)\leq U$ and integral demand $0\leq \d(v)\leq w(v)$. Given parameters $0<\epsilon\leq 1$, $1\leq r\leq \lfloor\log_{20}\d(V(G))\rfloor$, there is an algorithm that computes an $(\epsilon,\phi)$-vertex expander decomposition of $G$, where $\phi=\epsilon/(\log^{O(r)}U\log^{O(r^{5})}(m\log U))$. The algorithm can be deterministic with running time $O(m^{1+o(1)+O(1/r)}\cdot U^{1+O(1/r)}\cdot\log^{O(r^{4})}(mU)/\phi)$, or randomized with running time $O(m^{1+o(1)}\cdot(mU)^{O(1/r)}\cdot\log^{O(r^{4})}(mU))$ and high correct probability.
\label{thm:ComplexDecomp}
\end{theorem}

\begin{remark}
In the following of \Cref{sect:VertexExpander}, we only discuss the less efficient deterministic algorithm in \Cref{thm:ComplexDecomp}. It suffices for our application in \Cref{sect:LowDegreeHierarchy} because we have $\phi=1/n^{o(1)}$ and $U=O(1)$ in that scenario. We emphasize that we can improve the running time at a cost of making the algorithm randomized, by simply substituting the approximate vertex-capacitaed max flow algorithm in \Cref{lemma:DetVertexFlow} with the faster randomized version in \Cref{lemma:RandVertexFlow}.
\label{remark:DetDecomp}
\end{remark}

\begin{definition}[$\d$-matching]
For two sets $A,B$ of vertices with demand $\d(v)\geq 0$ for each $v\in A\cup B$ (assuming $\d(A)\leq \d(B)$), a $\d$-matching between $A$ and $B$ is an edge-weighted bipartite graph of $A$ and $B$ such that for each $v\in A\cup B$, the weighted degree (denoted by $M(v)$) is at most $\d(v)$. The value of $M$ is the total weight of edges, which is equal to $M(A)=\sum_{v\in A}M(v)$. We say this matching is \textit{perfect} if $M(A)=\d(A)$.
\label{def:dMatching}
\end{definition}

\begin{definition}[Embedding]
Let $G=(V(G),E(G),w)$ be a graph with positive integral vertex weights $w$, and let $H=(V(H),E(H),w_{H})$ be an graph with $V(H)=V(G)$ and positive integral edge weights $w_{H}$. An \textit{embedding of $H$ into $G$} is a collection ${\cal P}$ of unweighted paths in $G$, where for each $e=(u,v)\in E(H)$, there are exactly $w_{H}(e)$ paths in ${\cal P}$ connecting $u$ and $v$. If there exists a value $\eta$ such that each vertex $v\in V(G)$ appears in at most $\eta\cdot w(v)$ paths in ${\cal P}$, we say that the embedding has \textit{vertex-congestion} $\eta$. We use $E({\cal P})$ to denote edges in $E(G)$ involved in ${\cal P}$.
\label{def:embedding}
\end{definition}

\begin{lemma}
Let $G=(V(G),E(G),w,\d)$ be an $n$-vertex $m$-edge graph with, for each $v\in V(G)$, integral weights $1\leq w(v)\leq U$ and integral demands $0\leq \d(v)\leq w(v)$. Let $(A,B)$ be an edge cut of $G$ with $\d(A)\leq \d(B)$. Given $z\geq 0,0<\phi\leq 1$, there is a deterministic algorithm that computes
\begin{itemize}
    \item either a $\d$-matching $M$ between $A$ and $B$ with value at least $\d(A)-z$ such that there is an embedding ${\cal P}$ of $M$ into $G$ with vertex-congestion $O(\log (nU)/\phi)$; or
    \item a vertex cut $(L,S,R)$ in $G$ with $\d(L),\d(R)> z$ and $h_{G}(L,S,R)\leq \phi$. 
\end{itemize}
The running time of this algorithm is $O(m^{1+o(1)}U\log U/\phi)$. If the output is the $\d$-matching $M$, the algorithm can further output the set $E({\cal P})$ of ${\cal P}$.
\label{thm:RandMatchingPlayer}
\end{lemma}

\section{Omitted Proof}
\label{Appendix:OmittedProof}
\subsection{Proof of \Cref{thm:RandMatchingPlayer}}
\label{proof:DetMatchingPlayer}

We start by constructing the following vertex-capacitated graph $G'=(V(G'),E(G'),c)$. The vertex set $V(G')$ is $V(G)\cup\{u_{A}\mid u\in A\}\cup\{v_{B}\mid v\in B\}\cup\{s,t\}$, where $c(v)=\lceil 1/\phi\rceil\cdot w(v)$ for each $v\in V(G)$, $c(u_{A})=\d(u)$ for each $u_{A}$ corresponds to some $u\in A$, $c(v_{B})=\d(v)$ for each $v_{B}$ corresponds to some $v\in B$, and $s$ and $t$ are the source and the sink without capacity constraints. The edge set $E(G')$ is $E(G)\cup\{(s,u_{A}),(u_{A},u)\mid u\in A\}\cup\{(v,v_{B}),(v_{B},t)\mid v\in B\}$.

\section{Deterministic Approximate Vertex-Capacitated Max Flow}
\label{sect:DetVertexFlow}

\begin{lemma}[Almost-Linear-Time Approximate Vertex-Capacitated Max Flow, \cite{BGS21}] For any constant $1/\polylog(n)< \epsilon < 1$, consider an $n$-vertex $m$-edge undirected graph $G=(V(G),E(G),c)$ with vertex capacity function $c:V(G)\setminus\{s,t\}\to \mathbb{R}_{>0}$. Let $s,t\in V(G)$ be source and sink vertices without capacity constraints such that $s$ and $t$ are not directly connected by an edge. Then, there is a randomized algorithm that computes, with high probability,
\begin{itemize}
    \item a feasible flow $f$ that sends a $(1-\epsilon)$-fraction of the max flow value from $s$ to $t$, and
    \item a cut $S\subseteq V(G)\setminus\{s,t\}$ whose deletion will disconnect $s$ from $t$, with total capacities no more than $(1+\epsilon)$ times the min cut value.
\end{itemize}
The algorithm runs in $O(m^{1+o(1)}\log\log C)$ time, where $C$ is the maximum capacity ratio.
\label{lemma:RandVertexFlow}
\end{lemma}

\begin{lemma}[Deterministic Approximate Vertex-Capacitated Max Flow] For any constant $1/\polylog(n)< \epsilon < 1$, consider an $n$-vertex $m$-edge undirected graph $G=(V(G),E(G),c)$ with vertex capacity function $c:V(G)\to [1,C]\cup\{\infty\}$. Let $s,t\in V(G)$ be source and sink vertices such that $s$ and $t$ are not directly connected by an edge and $c(s),c(t)=\infty$, and they are the only vertices with infinite capacity. Then, there is a deterministic algorithm that computes,
\begin{itemize}
    \item a feasible flow $f$ that sends a $(1-\epsilon)$-fraction of the max flow value from $s$ to $t$, and
    \item a cut $S\subseteq V(G)\setminus\{s,t\}$ whose deletion will disconnect $s$ from $t$, with total capacities no more than $(1+\epsilon)$ times the min cut value.
\end{itemize}
The algorithm runs in $O(m^{1+o(1)}\polylog C+n^{o(1)}C_{\ssum})$ time, where $C$ is the maximum capacity and $C_{\ssum}=\sum_{v\in V(G)\setminus\{s,t\}}c(v)$ denotes the total capacities of finite capacitated vertices.
\label{lemma:DetVertexFlow}
\end{lemma}

\section{Expander Decomposition for Hypergraphs}
\label{sect:HyperDecomp}

We consider a hypergraph $H=(V(H),E(H))$ such that each edge $e\in E(H)$ is represented by a non-empty subset of vertices, i.e. $e\subseteq V(H)$ and $e\neq\emptyset$. Given a subset $U\subseteq V(H)$, we use $H[U]$ to denote the vertex-induced subgraph with vertex set $V(H[U])=U$ and edge set $E(H[U])=\{e\cap U\mid e\in E(H),e\cap U\neq\emptyset\}$\footnote{We consider $E(H[U])$ as a multiset. Namely, for each $e\in E(H),e\cap U\neq\emptyset$, we create a copy of $e\cap U$ in $E(H[U])$.}. Note that in our notation, for a hyperedge $e$ partially intersects $U$, we keep the part $e\cap U$ in $E(H[U])$.

\begin{definition}[Conductance on Hypergraphs]
Let $H=(V(H),E(H))$ be a hypergraph. For any cut $(S,\bar{S})$ with $\emptyset \subset S\subset V(H)$ and $\bar{S}=V(H)\setminus S$, its \textit{conductance} is 
\[
    \Phi_{H}(S)=\frac{|E_{H}(S,\bar{S})|}{\min\{|E(H[S])|,|E(H[\bar{S}])|\}},
\]
where $E_{H}(S,\bar{S})=\{e\mid e\in E(H),e\cap S\neq\emptyset,e\cap\bar{S}\neq\emptyset\}$ denote edges crossing the cut. The conductance of $H$, denoted by $\Phi(H)$, is the minimum conductance of any cut $(S,\bar{S})$ with $\emptyset \subset S\subset V(H)$.
\label{def:HyperConductance}
\end{definition}

\begin{definition}[Expander Decomposition on Hypergraphs]
Let $H=(V(H),E(H))$ be a hypergraph. For parameters $0\leq\phi\leq\epsilon\leq 1$, an $(\epsilon,\phi)$-expander decomposition of $H$ is a partition ${\cal H}=(V_{1},...,V_{k})$ of $V(H)$ such that
\begin{itemize}
    \item for all $V_{i}\in{\cal H}$, $\Phi(H[V_{i}])\geq \phi$; and
    \item the number of crossing edges, i.e. edges $e\in E(H)$ such that $\forall V_{i}\in {\cal H},e\nsubseteq V_{i}$, is at most $\epsilon|E(H)|$. 
\end{itemize}
\label{def:HyperDecomp}
\end{definition}

\begin{definition}
Let $G=(V(G),E(G),w,\d)$ be a graph with weight $w(v)\geq 0$ and demand $\d(v)\geq 0$ for each vertex $v\in V(G)$. For parameters $\epsilon>\phi> 0$, an \textit{$(\epsilon,\phi)$-neighbor-included vertex expander decomposition} of $G$ is a collections of pairs of subgraphs ${\cal G}=\{(V_{1},W_{1}),...,(V_{k},W_{k})\}$ such that $V_{1},...,V_{k}$ are disjoint (some $V_{i}$ can possibly be empty). Let $X=V(G)\setminus (\bigcup_{i} V_{i}$) denote the \textit{separator}. Then ${\cal G}$ further satisfies the following.
\begin{itemize}
    \item[(1)] For all $(V_{i},W_{i})\in{\cal G}$, $V_{i}\cup N_{G}(V_{i})\subseteq W_{i}$.
    \item[(2)] $X=\bigcup_{i}W_{i}\setminus V_{i}$.
    \item[(3)] For all $(V_{i},W_{i})\in{\cal G}$, $h(G[W_{i}])\geq\phi$.
    \item[(4)] $\sum_{i} w(W_{i}\setminus V_{i})\leq \epsilon\cdot \d(V(G))$.
\end{itemize}
\label{def:DecompWithNeighbors}
\end{definition}

\begin{lemma}
Let $G=(V(G),E(G),w,\d)$ be an $n$-vertex $m$-edge graph with, for each $v\in V(G)$, integral weight $1\leq w(v)\leq U$ and integral demand $0\leq \d(v)\leq w(v)$. Given parameters $0<\epsilon\leq 1/2$ and $1\leq r\leq \lfloor\log_{20}\d(V(G))\rfloor$, there is a deterministic algorithm that computes a vertex cut $(L,S,R)$ (possibly $L=S=\emptyset$) of $G$ with $w(S)\leq \epsilon\cdot\d(L\cup S)$, which further satisfies
\begin{itemize}
    \item either $\d(L\cup S),\d(R\cup S)\geq \d(V(G))/3$; or
    \item $\d(R\cup S)\geq \d(V(G))/2$ and $h(G[R\cup S])\geq \phi$ for some $\phi=\epsilon/\log^{O(r)}U\log^{O(r^{5})}(m\log U)$.
\end{itemize}
The running time of this algorithm is $O(m^{1+o(1)+O(1/r)}\cdot U^{1+O(1/r)}\cdot\log^{O(r^{4})}(mU)/\phi)$.
\label{lemma:CutOrCertifyBoundary}
\end{lemma}
